import { describe, it } from 'vitest';
import { requireCourse } from './index';
import type { Hole } from './types';

const draw = (hole: Hole): string => {
  const xs = hole.surfaces.flatMap((s) => [s.transform.position.x - s.size.x / 2, s.transform.position.x + s.size.x / 2]);
  const zs = hole.surfaces.flatMap((s) => [s.transform.position.z - s.size.z / 2, s.transform.position.z + s.size.z / 2]);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minZ = Math.min(...zs), maxZ = Math.max(...zs);
  const cols = 38, rows = 20;
  const grid = Array.from({ length: rows }, () => Array.from({ length: cols }, () => ' '));
  for (let r = 0; r < rows; r += 1) {
    for (let c = 0; c < cols; c += 1) {
      const x = minX + ((c + 0.5) / cols) * (maxX - minX);
      const z = maxZ - ((r + 0.5) / rows) * (maxZ - minZ);
      const slab = hole.surfaces.find((s) => Math.abs(x - s.transform.position.x) <= s.size.x / 2 && Math.abs(z - s.transform.position.z) <= s.size.z / 2);
      if (slab) grid[r]![c] = slab.shape === 'ramp' ? '/' : slab.transform.position.y > 0.2 ? '#' : slab.transform.position.y < -0.2 ? '_' : '.';
    }
  }
  const mark = (px: number, pz: number, ch: string) => {
    const c = Math.round(((px - minX) / (maxX - minX)) * (cols - 1));
    const r = Math.round(((maxZ - pz) / (maxZ - minZ)) * (rows - 1));
    if (grid[r] && grid[r]![c] !== undefined) grid[r]![c] = ch;
  };
  mark(hole.spawn.x, hole.spawn.z, 'T');
  mark(hole.cup.position.x, hole.cup.position.z, 'O');
  return grid.map((row) => row.join('')).join('\n');
};

describe('layout report', () => {
  for (const n of [4, 7, 9]) {
    it(`prints hole ${n} of each themed course`, () => {
      for (const id of ['ancient-temple', 'arctic-base', 'volcano']) {
        const hole = requireCourse(id).holes[n - 1]!;
        const kinds = [...new Set(hole.obstacles.map((o) => o.type))].join(', ');
        console.log(`\n### ${id} hole ${n} - ${hole.name} (par ${hole.par}, ${hole.surfaces.length} slabs)\nmechanics: ${kinds}\n${draw(hole)}`);
      }
    });
  }
});
EOF
